-- Facebook 获客分析 V1：高置信品名归一回填
-- 目标库：db_prize_cal
-- 映射品名：2587
-- 预计更新绩效记录：7390
-- 映射 SHA256：7687f071893e716f963c492b1d4a6ffc1bf61a75aca9e3674bd42396b7e1240f
-- UNKNOWN 和置信度不足 0.90 的记录不在本次范围。

SET NAMES utf8mb4;
USE `db_prize_cal`;

CREATE TABLE IF NOT EXISTS `z_plan_acq_product_20261026_v1` (
    `raw_product_name` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `normalized_category` VARCHAR(32) NOT NULL,
    `source` VARCHAR(16) NOT NULL,
    `confidence` DECIMAL(6,4) NOT NULL,
    `expected_order_count` INT UNSIGNED NOT NULL,
    `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`raw_product_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `z_bak_acq_product_20261026_v1` LIKE `t_performance_statement`;

DELIMITER $$
DROP PROCEDURE IF EXISTS `assert_acq_category_empty_20261026_v1`$$
CREATE PROCEDURE `assert_acq_category_empty_20261026_v1`()
BEGIN
    IF (SELECT COUNT(*) FROM `z_plan_acq_product_20261026_v1`) <> 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '迁移终止：计划表非空，可能已执行过';
    END IF;
    IF (SELECT COUNT(*) FROM `z_bak_acq_product_20261026_v1`) <> 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '迁移终止：备份表非空，可能已执行过';
    END IF;
END$$
DELIMITER ;

CALL `assert_acq_category_empty_20261026_v1`();
DROP PROCEDURE `assert_acq_category_empty_20261026_v1`;


DELIMITER $$
DROP PROCEDURE IF EXISTS `validate_acq_category_plan_20261026_v1`$$
CREATE PROCEDURE `validate_acq_category_plan_20261026_v1`()
BEGIN
    IF (SELECT COUNT(*) FROM `z_plan_acq_product_20261026_v1`) <> 2587 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '迁移终止：映射品名数不符合预期';
    END IF;
    IF (SELECT COALESCE(SUM(`expected_order_count`), 0) FROM `z_plan_acq_product_20261026_v1`) <> 7390 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '迁移终止：计划订单数不符合预期';
    END IF;
    IF (SELECT COUNT(*)
        FROM `t_performance_statement` performance
        JOIN `z_plan_acq_product_20261026_v1` plan
          ON BINARY TRIM(performance.`product_name`) = BINARY plan.`raw_product_name`) <> 7390 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '迁移终止：数据库当前匹配行数与 dry-run 不一致';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM `z_plan_acq_product_20261026_v1` plan
        LEFT JOIN `t_performance_statement` performance
          ON BINARY TRIM(performance.`product_name`) = BINARY plan.`raw_product_name`
        GROUP BY plan.`raw_product_name`, plan.`expected_order_count`
        HAVING COUNT(performance.`id`) <> plan.`expected_order_count`
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '迁移终止：至少一个品名的匹配票数已变化';
    END IF;
END$$
DELIMITER ;

CALL `validate_acq_category_plan_20261026_v1`();
DROP PROCEDURE `validate_acq_category_plan_20261026_v1`;

SELECT performance.*
FROM `t_performance_statement` performance
JOIN `z_plan_acq_product_20261026_v1` plan
  ON BINARY TRIM(performance.`product_name`) = BINARY plan.`raw_product_name`;
COMMIT;

DELIMITER $$
DROP PROCEDURE IF EXISTS `apply_acq_category_20261026_v1`$$
CREATE PROCEDURE `apply_acq_category_20261026_v1`()
BEGIN
    DECLARE changed_rows INT DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    IF (SELECT COUNT(*) FROM `z_bak_acq_product_20261026_v1`) <> 7390 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '迁移终止：行级备份数量不符合预期';
    END IF;

    START TRANSACTION;
    UPDATE `t_performance_statement` performance
    JOIN `z_plan_acq_product_20261026_v1` plan
      ON BINARY TRIM(performance.`product_name`) = BINARY plan.`raw_product_name`
    SET performance.`product_name` = plan.`normalized_category`,
        performance.`updated_at` = CURRENT_TIMESTAMP;

    SET changed_rows = ROW_COUNT();
    IF changed_rows <> 7390 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '迁移终止：实际更新行数不符合预期';
    END IF;
    COMMIT;
END$$
DELIMITER ;

CALL `apply_acq_category_20261026_v1`();
DROP PROCEDURE `apply_acq_category_20261026_v1`;

SELECT plan.`normalized_category`, plan.`source`, COUNT(*) AS `mapped_names`,
       SUM(plan.`expected_order_count`) AS `updated_orders`
FROM `z_plan_acq_product_20261026_v1` plan
GROUP BY plan.`normalized_category`, plan.`source`
ORDER BY plan.`normalized_category`, plan.`source`;

-- 计划表和行级备份表保留到人工验收完成，删除需另行审批。
